<template><div class="form-page"><div class="form-wrap"><form class="form-card" @submit.prevent="submit"><img src="/logo.svg" style="width:155px;margin-bottom:24px"/><h1>Create your account</h1><p class="muted">Browse BraTips freely. Sign up when you're ready to play a pick.</p><div v-if="error" class="error">{{error}}</div><div class="field"><label>Full name</label><input v-model="name" required minlength="2"/></div><div class="field"><label>Email</label><input v-model="email" type="email" required/></div><div class="field"><label>Password</label><input v-model="password" type="password" required minlength="8"/></div><button class="btn">Create account</button><div class="switch">Want to publish your own picks? <RouterLink to="/tipster-signup" style="color:var(--pink);font-weight:700">Sign up as a tipster</RouterLink></div></form></div></div></template>
<script setup lang="ts">import {ref} from 'vue';import {RouterLink,useRouter} from 'vue-router';import {useAuth} from '../stores/auth';const auth=useAuth(),router=useRouter();const name=ref(''),email=ref(''),password=ref(''),error=ref('');async function submit(){try{await auth.register(name.value,email.value,password.value);await auth.login(email.value,password.value);router.push('/dashboard')}catch(e:any){error.value=e.message}}</script>
